-- Generated by: python -m pdm_common.store --ddl postgres > db/init/001_schema.sql
-- The schema is declared in lib/pdm_common/store.py; edit it there and regenerate.
DO $$ BEGIN CREATE EXTENSION IF NOT EXISTS timescaledb;
EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'timescaledb not available: plain tables'; END $$;


-- accepted records with out_of_range flags (ING-07); append-only
CREATE TABLE IF NOT EXISTS telemetry (
  asset_id TEXT,
  ts TIMESTAMPTZ,
  seq BIGINT,
  signals JSONB,
  out_of_range JSONB,
  PRIMARY KEY (asset_id, ts)
);

-- 10-minute windows with their features, as ingest published them
CREATE TABLE IF NOT EXISTS windows (
  asset_id TEXT,
  window_start TIMESTAMPTZ,
  window_end TIMESTAMPTZ,
  features JSONB,
  n_bridged BIGINT,
  profile_sha256 TEXT,
  PRIMARY KEY (asset_id, window_end)
);

-- one score per window with per-feature error (DET-06, DET-07)
CREATE TABLE IF NOT EXISTS scores (
  asset_id TEXT,
  window_start TIMESTAMPTZ,
  window_end TIMESTAMPTZ,
  score DOUBLE PRECISION,
  errors JSONB,
  threshold DOUBLE PRECISION,
  alert BOOLEAN,
  detector_run_id TEXT,
  profile_sha256 TEXT,
  PRIMARY KEY (asset_id, window_end)
);

-- P(24, 72, 168 h) with bounds (PRG-02, PRG-05)
CREATE TABLE IF NOT EXISTS prognoses (
  asset_id TEXT,
  ts TIMESTAMPTZ,
  probabilities JSONB,
  attribution JSONB,
  inputs JSONB,
  model_run_id TEXT,
  input_from TIMESTAMPTZ,
  input_to TIMESTAMPTZ,
  PRIMARY KEY (asset_id, ts)
);

-- records that failed validation (ING-06)
CREATE TABLE IF NOT EXISTS quarantine (
  id BIGSERIAL,
  asset_id TEXT,
  received_at TIMESTAMPTZ,
  error_code TEXT,
  error_text TEXT,
  payload TEXT,
  PRIMARY KEY (id)
);

-- state changes only through incident_events (INC-05)
CREATE TABLE IF NOT EXISTS incidents (
  incident_id TEXT,
  asset_id TEXT,
  opened_at TIMESTAMPTZ,
  as_of TIMESTAMPTZ,
  gate JSONB,
  state TEXT,
  ne107 TEXT,
  triage JSONB,
  last_pass_at TIMESTAMPTZ,
  episode_closed_at TIMESTAMPTZ,
  closed_at TIMESTAMPTZ,
  profile_sha256 TEXT,
  detector_run_id TEXT,
  PRIMARY KEY (incident_id)
);

-- every transition (INC-05)
CREATE TABLE IF NOT EXISTS incident_events (
  id BIGSERIAL,
  incident_id TEXT,
  from_state TEXT,
  to_state TEXT,
  actor TEXT,
  at TIMESTAMPTZ,
  cause TEXT,
  PRIMARY KEY (id)
);

-- every gate decision with its trajectory (INC-02)
CREATE TABLE IF NOT EXISTS gate_log (
  id BIGSERIAL,
  asset_id TEXT,
  at TIMESTAMPTZ,
  decision TEXT,
  incident_id TEXT,
  params JSONB,
  trajectory JSONB,
  PRIMARY KEY (id)
);

-- every NE 107 change with its cause (INC-07, INT-03)
CREATE TABLE IF NOT EXISTS status_log (
  id BIGSERIAL,
  asset_id TEXT,
  at TIMESTAMPTZ,
  from_status TEXT,
  to_status TEXT,
  cause TEXT,
  PRIMARY KEY (id)
);

-- every tool result, stored before the model sees it (AGT-03)
CREATE TABLE IF NOT EXISTS tool_results (
  result_id TEXT,
  incident_id TEXT,
  tool TEXT,
  arguments JSONB,
  as_of TIMESTAMPTZ,
  output JSONB,
  created_at TIMESTAMPTZ,
  PRIMARY KEY (result_id)
);

-- the audit record of each agent run (AGT-11)
CREATE TABLE IF NOT EXISTS agent_traces (
  trace_id TEXT,
  incident_id TEXT,
  arm TEXT,
  model TEXT,
  skills JSONB,
  messages JSONB,
  tool_calls JSONB,
  budget JSONB,
  outcome TEXT,
  started_at TIMESTAMPTZ,
  finished_at TIMESTAMPTZ,
  PRIMARY KEY (trace_id)
);

-- the agent run's state after each step, so a restarted agent resumes it
CREATE TABLE IF NOT EXISTS agent_checkpoints (
  trace_id TEXT,
  incident_id TEXT,
  arm TEXT,
  node TEXT,
  state JSONB,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (trace_id)
);

-- brief_v1 documents; a repair adds a row (BRF-01)
CREATE TABLE IF NOT EXISTS briefs (
  brief_id TEXT,
  incident_id TEXT,
  document JSONB,
  evidence_state TEXT,
  valid BOOLEAN,
  validation JSONB,
  trace_id TEXT,
  arm TEXT,
  created_at TIMESTAMPTZ,
  PRIMARY KEY (brief_id)
);

-- approve, edit and approve, or reject (HIL-05)
CREATE TABLE IF NOT EXISTS decisions (
  decision_id TEXT,
  brief_id TEXT,
  incident_id TEXT,
  reviewer TEXT,
  action TEXT,
  reason TEXT,
  work_order JSONB,
  diff TEXT,
  evidence_sha256 TEXT,
  versions JSONB,
  trace_id TEXT,
  at TIMESTAMPTZ,
  PRIMARY KEY (decision_id)
);

-- queued by an approval only; status set by the connector (INT-04, HIL-06)
CREATE TABLE IF NOT EXISTS work_orders (
  wo_id TEXT,
  decision_id TEXT,
  incident_id TEXT,
  asset_id TEXT,
  body JSONB,
  text_sha256 TEXT,
  status TEXT,
  attempts BIGINT,
  next_attempt_at TIMESTAMPTZ,
  last_error TEXT,
  reference TEXT,
  sent_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (wo_id),
  UNIQUE (decision_id)
);

-- the source register (AGT-10)
CREATE TABLE IF NOT EXISTS corpus_documents (
  doc_id TEXT,
  title TEXT,
  url TEXT,
  accessed TEXT,
  licence TEXT,
  sha256 TEXT,
  path TEXT,
  kind TEXT,
  PRIMARY KEY (doc_id)
);

-- sanitised passages with offsets
CREATE TABLE IF NOT EXISTS corpus_passages (
  doc_id TEXT,
  passage_no BIGINT,
  start_offset BIGINT,
  end_offset BIGINT,
  text TEXT,
  PRIMARY KEY (doc_id, passage_no)
);

-- the blinded study's records (HIL-09)
CREATE TABLE IF NOT EXISTS study_sessions (
  id BIGSERIAL,
  session_id TEXT,
  reviewer TEXT,
  arm TEXT,
  incident_id TEXT,
  order_no BIGINT,
  rating BIGINT,
  seconds DOUBLE PRECISION,
  decision TEXT,
  consent BOOLEAN,
  at TIMESTAMPTZ,
  PRIMARY KEY (id)
);

-- G8 stretch: decoded device status
CREATE TABLE IF NOT EXISTS device_events (
  asset_id TEXT,
  ts TIMESTAMPTZ,
  device TEXT,
  object TEXT,
  attribute TEXT,
  raw_value TEXT,
  decoded TEXT,
  severity TEXT,
  ne107_class TEXT,
  PRIMARY KEY (asset_id, ts, device, attribute)
);

-- drift checks per signal and regime (OPS-04)
CREATE TABLE IF NOT EXISTS drift_alerts (
  id BIGSERIAL,
  asset_id TEXT,
  at TIMESTAMPTZ,
  regime TEXT,
  signal TEXT,
  distance DOUBLE PRECISION,
  threshold DOUBLE PRECISION,
  alert BOOLEAN,
  PRIMARY KEY (id)
);

-- recorded team approvals for promotion (OPS-07)
CREATE TABLE IF NOT EXISTS promotions (
  id BIGSERIAL,
  model_name TEXT,
  version TEXT,
  alias TEXT,
  requested_by TEXT,
  approved_by TEXT,
  approval_ref TEXT,
  at TIMESTAMPTZ,
  outcome TEXT,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS tool_results_incident_id_idx ON tool_results (incident_id);
CREATE INDEX IF NOT EXISTS briefs_incident_id_idx ON briefs (incident_id);
CREATE INDEX IF NOT EXISTS decisions_incident_id_idx ON decisions (incident_id);
CREATE INDEX IF NOT EXISTS agent_traces_incident_id_idx ON agent_traces (incident_id);
CREATE INDEX IF NOT EXISTS agent_checkpoints_incident_id_idx ON agent_checkpoints (incident_id);
CREATE INDEX IF NOT EXISTS incident_events_incident_id_idx ON incident_events (incident_id);
CREATE INDEX IF NOT EXISTS work_orders_status_idx ON work_orders (status);
CREATE INDEX IF NOT EXISTS incidents_asset_id_state_idx ON incidents (asset_id, state);
CREATE INDEX IF NOT EXISTS gate_log_asset_id_at_idx ON gate_log (asset_id, at);
CREATE INDEX IF NOT EXISTS study_sessions_session_id_idx ON study_sessions (session_id);

CREATE OR REPLACE FUNCTION forbid_change() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION '% is insert-only', TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS incident_events_insert_only ON incident_events;
CREATE TRIGGER incident_events_insert_only BEFORE UPDATE OR DELETE ON incident_events
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS gate_log_insert_only ON gate_log;
CREATE TRIGGER gate_log_insert_only BEFORE UPDATE OR DELETE ON gate_log
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS status_log_insert_only ON status_log;
CREATE TRIGGER status_log_insert_only BEFORE UPDATE OR DELETE ON status_log
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS tool_results_insert_only ON tool_results;
CREATE TRIGGER tool_results_insert_only BEFORE UPDATE OR DELETE ON tool_results
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS agent_traces_insert_only ON agent_traces;
CREATE TRIGGER agent_traces_insert_only BEFORE UPDATE OR DELETE ON agent_traces
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS briefs_insert_only ON briefs;
CREATE TRIGGER briefs_insert_only BEFORE UPDATE OR DELETE ON briefs
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS decisions_insert_only ON decisions;
CREATE TRIGGER decisions_insert_only BEFORE UPDATE OR DELETE ON decisions
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS study_sessions_insert_only ON study_sessions;
CREATE TRIGGER study_sessions_insert_only BEFORE UPDATE OR DELETE ON study_sessions
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DROP TRIGGER IF EXISTS promotions_insert_only ON promotions;
CREATE TRIGGER promotions_insert_only BEFORE UPDATE OR DELETE ON promotions
  FOR EACH ROW EXECUTE FUNCTION forbid_change();

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'timescaledb') THEN
    PERFORM create_hypertable('telemetry', 'ts', if_not_exists => TRUE);
    PERFORM create_hypertable('windows', 'window_end', if_not_exists => TRUE);
    PERFORM create_hypertable('scores', 'window_end', if_not_exists => TRUE);
    PERFORM create_hypertable('prognoses', 'ts', if_not_exists => TRUE);
  END IF;
END $$;
